static void Trocar(int[] v)
{
    v[0] = 10;
    v = new[] { 99 };
}

int[] numeros = { 1 };
Trocar(numeros);
Console.WriteLine(numeros[0]);

record Pessoa(string Nome, int Idade);

var a = new Pessoa("Ana", 30);
var b = a with { Idade = 31 };

Console.WriteLine($"{a == new Pessoa("Ana", 30)} {ReferenceEquals(a, b)} {a.Idade}");

static string Classificar(object? o) => o switch
{
    int n when n < 0 => "negativo",
    int => "inteiro",
    string { Length: 0 } => "vazio",
    string s => $"texto:{s.Length}",
    null => "nulo",
    _ => "outro"
};

Console.WriteLine(Classificar("abc") + " " + Classificar(-5) + " " + Classificar(2.5));

